types	CREATE TABLE `types` (
  `id` int NOT NULL,
  `u` bigint unsigned NOT NULL DEFAULT '18446744073709551615',
  `d` decimal(20,3) NOT NULL DEFAULT '-12345678901234567.890',
  `ch` char(8) NOT NULL DEFAULT 0xE7958CF09F9880,
  `v` varchar(20) NOT NULL DEFAULT '',
  `bin` binary(4) NOT NULL DEFAULT 0x00FF0000,
  `dt` datetime(6) NOT NULL DEFAULT '2024-02-29 12:34:56.123456',
  `tm` time(3) NOT NULL DEFAULT '-12:34:56.123',
  `en` enum('','a','界') NOT NULL DEFAULT '界',
  `st` set('a','b','界') NOT NULL DEFAULT 'a,界',
  `bits` bit(64) NOT NULL DEFAULT b'1111111111111111111111111111111111111111111111111111111111111111',
  `j` json DEFAULT NULL,
  `blob` blob,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC
